const r=$('Preparar Elección Pago Paciente').first().json;
const guardado=$input.first().json;
if(!['pendiente_liga','pendiente_transferencia'].includes(r.estado_pago)||guardado.estado_pago!==r.estado_pago||String(guardado.cita_id)!==String(r.cita_id))return [];
let starts_at=String(r.fecha||'');
if(/^\d{4}-\d{2}-\d{2}$/.test(starts_at)&&/^\d{2}:\d{2}$/.test(String(r.hora||'')))starts_at+=`T${r.hora}:00-06:00`;
if(!/^\d{4}-\d{2}-\d{2}T.*(?:Z|[+-]\d{2}:?\d{2})$/.test(starts_at)||!Number.isFinite(Date.parse(starts_at))||!r.telefono||!r.paciente_id)return [];
return [{json:{tipo:r.estado_pago==='pendiente_liga'?'liga_solicitada':'transferencia_elegida',paciente_id:String(r.paciente_id),cita_id:String(r.cita_id),telefono:r.telefono,starts_at,monto:Number(r.monto||0)}}];
